package android.database; public final class Cursor implements AutoCloseable{private final String[] names;private final Object[][] rows;private int index=-1;public Cursor(String[] n,Object[][] r){names=n;rows=r;}public boolean moveToNext(){return ++index<rows.length;}public boolean moveToFirst(){index=0;return rows.length>0;}public String getString(int i){return rows[index][i]==null?null:String.valueOf(rows[index][i]);}public long getLong(int i){return rows[index][i]==null?0:Long.parseLong(String.valueOf(rows[index][i]));}public int getInt(int i){return (int)getLong(i);}public int getColumnIndexOrThrow(String n){for(int i=0;i<names.length;i++)if(names[i].equals(n))return i;throw new IllegalArgumentException(n);}public void close(){}}
